/// 这个入口有没有 CFG 记录（即块数 ≥2）。
inline bool IsCfgFunc(uint32_t va) {
    uint32_t lo = 0, hi = kCfgFuncCount;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (kCfgFuncVA[mid] < va) lo = mid + 1; else hi = mid;
    }
    return lo < kCfgFuncCount && kCfgFuncVA[lo] == va;
}

